  function renderCenterBody(){renderCenterKpis();renderTimeTabs();var body=qs("#tailCenterBody");if(state.tab==="trash"){body.innerHTML=renderTrash();return}body.innerHTML=renderCenterToolbar()+'<div class="tail-filter-summary"><span id="tailFilterSummary"></span><div class="tail-panel-actions"><button class="tail-button" data-tail-action="batch-delete">批量筛除</button><button class="tail-button is-primary" data-tail-action="batch-assign">批量分派供应商</button></div></div><div class="tail-selection" id="tailSelection" hidden></div><div class="tail-table-wrap" id="tailPostTable"></div><footer class="tail-panel-foot"><span>当前列表全部为未分派主贴 · 本页20条</span><div class="tail-pagination"><button>‹</button><button class="is-active">1</button><button>›</button></div></footer>';renderPostTable();renderSelection();var filter=tabFilters[state.tab];qs("#tailFilterSummary").innerHTML=state.tab==="history"?"全部未分派历史数据，已分派内容请前往任务跟踪查看":"当前保存条件：<strong>"+filter.platform+" · "+filter.mediaLevel+" · 粉丝≥"+filter.fans+" · 互动≥"+filter.engagement+" · 增速≥"+filter.growth+"</strong>"}
  function renderCenterKpis(){var rows=centerEligiblePosts(),inTab=rows.filter(function(p){return matchesTab(p)&&matchesSavedFilter(p)}),data=[["当前信息量",inTab.length,"所选品牌当前时间段"],["未分派新闻数",inTab.length,"等待处理"]];qs("#tailKpis").innerHTML=data.map(kpi).join("")}
  function renderTimeTabs(){var eligible=centerEligiblePosts();qs("#tailTimeTabs").innerHTML=timeTabs.map(function(t){var n=eligible.filter(function(p){return p.slot===t.id}).length;return'<button class="tail-time-tab '+(state.tab===t.id?"is-active":"")+'" data-tail-tab="'+t.id+'"><strong>'+esc(t.name)+'</strong><span>'+t.range+' · '+n+'条</span></button>'}).join("")+'<button class="tail-time-tab is-history '+(state.tab==="history"?"is-active":"")+'" data-tail-tab="history"><strong>全部数据</strong><span>全部未分派历史</span></button><button class="tail-time-tab is-trash '+(state.tab==="trash"?"is-active":"")+'" data-tail-tab="trash"><strong>垃圾筐</strong><span>所选品牌 '+posts.filter(function(p){return p.deleted&&brandSelected(p)}).length+' 条</span></button>'}
  function renderCenterToolbar(){var configure=tabFilters[state.tab]?'<div class="tail-toolbar-config"><span>筛选条件</span><button class="tail-button" data-tail-action="configure-tab">配置当前筛选</button></div>':'';return'<section class="tail-toolbar is-center is-no-status"><label class="tail-field"><span>关键词</span><input id="tailKeyword" value="'+esc(state.keyword)+'" placeholder="搜索标题、媒体、标签"></label>'+configure+'</section>'}
  function renderPostTable(){var rows=visiblePosts(),el=qs("#tailPostTable");if(!rows.length){el.innerHTML='<div class="tail-empty">所选品牌和当前条件下没有待分派信息</div>';return}el.innerHTML='<table class="tail-table"><thead><tr><th><input id="tailSelectAll" type="checkbox"></th><th>主贴信息</th><th>品牌 / 车型</th><th>媒体 / 账号</th><th>传播表现</th><th>标签</th><th>状态</th><th>操作</th></tr></thead><tbody>'+rows.map(function(p){return'<tr><td><input type="checkbox" data-post-select="'+p.id+'" '+(state.selected.indexOf(p.id)>-1?'checked':'')+'></td><td>'+infoCell(p)+'</td><td><strong>'+esc(p.brand)+'</strong><br><span class="tail-muted">'+esc(p.model)+'</span></td><td>'+esc(p.platform)+'<br><span class="tail-muted">'+esc(p.media)+' · '+format(p.followers)+'粉丝</span></td><td>互动 '+format(p.engagement)+'<br><span class="tail-muted">赞 '+format(p.likes)+' · 评 '+format(p.comments)+' · 转 '+format(p.reposts)+'</span></td><td>'+tags(p.tags)+'</td><td><span class="tail-status is-warn">未分派</span></td><td><div class="tail-row-actions"><button class="tail-button" data-tail-action="open-original" data-post-id="'+p.id+'">原文</button><button class="tail-button is-primary" data-tail-action="assign-one" data-post-id="'+p.id+'">分派</button><button class="tail-button is-danger" data-tail-action="delete-one" data-post-id="'+p.id+'">删除</button></div></td></tr>'}).join("")+'</tbody></table>'}
  function renderSelection(){var el=qs("#tailSelection");if(!el||!state.selected.length){if(el)el.hidden=true;return}el.hidden=false;el.innerHTML='<span>已选择 <strong>'+state.selected.length+'</strong> 条主贴，请使用上方批量操作</span>'}
  function renderTrash(){var rows=posts.filter(function(p){return p.deleted&&brandSelected(p)});return'<div class="tail-filter-summary"><span>仅展示所选品牌今天删除的信息，明日自动清空</span></div><div class="tail-table-wrap">'+(rows.length?'<table class="tail-table"><thead><tr><th>主贴信息</th><th>品牌</th><th>媒体</th><th>原时间段</th><th>删除时间</th><th>操作</th></tr></thead><tbody>'+rows.map(function(p){var t=findTime(p.slot);return'<tr><td>'+infoCell(p)+'</td><td>'+esc(p.brand)+'</td><td>'+esc(p.platform)+' · '+esc(p.media)+'</td><td>'+esc(t.name)+'<br><span class="tail-muted">'+t.range+'</span></td><td>'+esc(p.deletedAt)+'</td><td><button class="tail-button" data-tail-action="restore-post" data-post-id="'+p.id+'">取消删除</button></td></tr>'}).join("")+'</tbody></table>':'<div class="tail-empty">所选品牌垃圾筐暂无信息</div>')+'</div>'}


  function renderSettings(){
    var brand=activeBrand(),config=activeBrandConfig(),projects=selectedBrandProjects();
    qs("#tailContent").innerHTML='<section class="tail-panel tail-brand-settings"><div class="tail-brand-admin-bar"><div><strong>品牌数据配置</strong><span>当前 '+tailBrands.length+' 个品牌，每个品牌独立配置数据源、初筛条件和AI规则</span></div><button class="tail-button" data-tail-action="open-brand-manager">管理品牌</button></div><nav class="tail-brand-tabs" aria-label="品牌配置">'+tailBrands.map(function(item){return'<button class="'+(item.id===brand.id?'is-active':'')+'" data-tail-brand="'+item.id+'"><strong>'+item.name+'</strong><span>'+activeConfigFor(item.id).projectIds.length+' 个数据源</span></button>'}).join("")+'</nav><header class="tail-brand-overview"><div><span class="tail-eyebrow">当前配置品牌</span><h2>'+brand.name+'</h2><p>'+brand.desc+'。以下数据源、初筛条件和AI规则仅对'+brand.name+'生效。</p></div><div class="tail-brand-stats"><span><b>'+projects.length+'</b> 个监测项目</span><span><b>'+config.platforms.length+'</b> 个具体媒体</span><span><b>'+(config.aiEnabled?'已开启':'已关闭')+'</b> AI维护</span></div></header><div class="tail-settings-body">'+brandSettingsSource()+brandSettingsCleaning()+'</div><footer class="tail-save-bar"><span>保存后仅影响'+brand.name+'新进入的数据，不回溯修改历史数据。</span><button class="tail-button is-primary" data-tail-action="save-settings">保存'+brand.name+'配置</button></footer></section>'
  }
  function brandSettingsSource(){
    var brand=activeBrand(),rows=selectedBrandProjects();
    return'<section class="tail-settings-section"><div class="tail-block-head"><div class="tail-section-heading"><div class="tail-section-index">1</div><div><h2>'+brand.name+'数据源</h2><p>先确定该品牌从哪些监测项目接收信息。项目很多时，通过搜索与筛选找到后添加到本品牌。</p></div></div><button class="tail-button is-primary" data-tail-action="open-brand-project-picker">添加监测项目</button></div><div class="tail-brand-source-list">'+(rows.length?rows.map(function(p){return'<article class="tail-brand-source"><div><strong>'+esc(p.name)+'</strong><span>'+p.sceneLabel+' · '+p.platforms.join("、")+' · 今日 '+format(p.today)+' 条</span></div><button class="tail-icon-button" title="从'+brand.name+'数据源中移除" data-tail-action="remove-brand-project" data-project-id="'+p.id+'">×</button></article>'}).join(""):'<div class="tail-project-empty">当前品牌尚未接入监测项目，请先添加数据源。</div>')+'</div></section>'
  }
  function brandSettingsCleaning(){
    var config=activeBrandConfig();
    return'<section class="tail-settings-section"><div class="tail-block-head"><div class="tail-section-heading"><div class="tail-section-index">2</div><div><h2>配置进入初筛库的数据</h2><p>信息需同时满足下方启用条件，才进入当前品牌尾翼数据中心；“不要的信息命中词”命中后直接排除。</p></div></div><span class="tail-rule-summary">已选 '+config.platforms.length+' 个具体媒体 · 粉丝 ≥ '+format(config.followerMin)+' · 评论 ≥ '+format(config.commentMin)+'</span></div><div class="tail-expression-grid">'+expressionField("includeExpression","我要的信息命中词","定义必须出现的品牌、车型或议题。支持 AND、OR、括号和词间距。",config.includeExpression,'例如：(坦克 OR "坦克700") AND (越野 OR 智能)')+expressionField("excludeExpression","我不要的信息命中词","定义明确排除的无关主题或营销内容，命中任一排除表达式即不进入。",config.excludeExpression,'例如：(招聘 OR 招标) OR NEAR("长城", "地产", 5)')+'</div><div class="tail-screening-groups">'+platformGroupSelector(config.platforms)+'<div class="tail-screen-row"><div><strong>传播量门槛</strong><span>账号粉丝量与该条信息评论数两个条件需同时满足。</span></div><div class="tail-number-fields"><label class="tail-field"><span>粉丝量</span><div class="tail-number-input"><b>≥</b><input type="number" min="0" step="1000" value="'+config.followerMin+'" data-brand-field="followerMin"></div></label><label class="tail-field"><span>评论数</span><div class="tail-number-input"><b>≥</b><input type="number" min="0" step="1" value="'+config.commentMin+'" data-brand-field="commentMin"></div></label></div></div>'+checkGroup("mediaLevels","媒体等级","选择一般媒体、重点媒体是否可以进入。",["一般","重点"],config.mediaLevels)+checkGroup("mentionTypes","提及类型","要求品牌词出现在标题、正文或两者任一位置。",["标题提及","正文提及"],config.mentionTypes)+checkGroup("mediaAttributes","媒体属性","依据数据端已有账号标签，选择允许进入的账号身份。",["媒体","官方","用户","经销商","领导人","广告号","后市场商家","其他"],config.mediaAttributes)+'</div></section><section class="tail-settings-section tail-ai-maintenance"><div class="tail-block-head"><div class="tail-section-heading"><div class="tail-section-index">3</div><div><h2>AI维护判定</h2><p>结构化条件通过后，可由AI阅读全文语义，继续排除“关键词命中但实际内容无关”的信息。</p></div></div><label class="tail-switch"><input type="checkbox" data-brand-toggle="aiEnabled" '+(config.aiEnabled?'checked':'')+'><span></span><b>'+(config.aiEnabled?'已开启':'已关闭')+'</b></label></div>'+(config.aiEnabled?'<label class="tail-field tail-ai-rules"><span>AI去除规则</span><textarea rows="8" data-brand-field="aiRules">'+esc(config.aiRules)+'</textarea><small>规则文字可按当前品牌业务调整。AI命中任一规则时排除该信息，并保留判定原因供追溯。</small></label>':'<div class="tail-ai-off">AI维护已关闭，信息仅按上方关键词、平台、数值和标签条件进入。</div>')+'</section>'
  }
  function expressionField(field,title,desc,value,placeholder){return'<label class="tail-expression-card"><strong>'+title+'</strong><span>'+desc+'</span><textarea rows="4" data-brand-field="'+field+'" placeholder="'+placeholder+'">'+esc(value)+'</textarea><div class="tail-expression-tools"><span>插入运算符</span>'+[[" AND ","AND"],[" OR ","OR"],["( )","括号"],[" NEAR(词1, 词2, 5) ","词间距"]].map(function(x){return'<button type="button" data-expression-field="'+field+'" data-expression-token="'+esc(x[0])+'">'+x[1]+'</button>'}).join("")+'</div></label>'}
  function checkGroup(field,title,desc,options,selected,extra){return'<div class="tail-screen-row"><div><strong>'+title+'</strong><span>'+desc+'</span></div><div class="tail-option-grid '+(extra||"")+'">'+options.map(function(item){return'<label class="tail-option"><input type="checkbox" data-brand-array="'+field+'" value="'+item+'" '+(selected.indexOf(item)>-1?'checked':'')+'><span>'+item+'</span></label>'}).join("")+'</div></div>'}
  function platformGroupSelector(selected){return'<div class="tail-screen-row is-platform-row"><div><strong>平台</strong><span>先按媒体类型批量选择，再精确选择该类型下需要进入的具体媒体。</span><em>已选 '+selected.length+' / '+allPlatformKeys().length+' 个媒体</em></div><div class="tail-platform-groups">'+platformGroups.map(function(group){var keys=group.items.map(function(item){return platformKey(group.id,item)}),count=keys.filter(function(key){return selected.indexOf(key)>-1}).length;return'<section class="tail-platform-group"><label class="tail-platform-type"><input type="checkbox" data-platform-group="'+group.id+'" '+(count===keys.length?'checked':'')+'><span>'+group.name+'</span><em>已选 '+count+'/'+keys.length+'</em></label><div class="tail-platform-items">'+group.items.map(function(item){var key=platformKey(group.id,item);return'<label class="tail-option"><input type="checkbox" data-brand-array="platforms" value="'+esc(key)+'" '+(selected.indexOf(key)>-1?'checked':'')+'><span>'+item+'</span></label>'}).join("")+'</div></section>'}).join("")+'</div></div>'}
  function platformKey(groupId,item){return groupId+"|"+item}
  function allPlatformKeys(){return platformGroups.reduce(function(rows,group){return rows.concat(group.items.map(function(item){return platformKey(group.id,item)}))},[])}
  function togglePlatformGroup(groupId,checked){var group=platformGroups.filter(function(item){return item.id===groupId})[0];if(!group)return;var selected=activeBrandConfig().platforms,keys=group.items.map(function(item){return platformKey(group.id,item)});keys.forEach(function(key){var index=selected.indexOf(key);if(checked&&index<0)selected.push(key);if(!checked&&index>-1)selected.splice(index,1)});rerenderSettingsAtScroll()}
  function rerenderSettingsAtScroll(){var y=window.scrollY;renderSettings();window.scrollTo(0,y)}
  function activeBrand(){return tailBrands.filter(function(item){return item.id===state.activeBrand})[0]||tailBrands[0]}
  function activeConfigFor(id){if(!state.brandConfigs[id])state.brandConfigs[id]=createBrandConfigs()[id];return state.brandConfigs[id]}
  function activeBrandConfig(){return activeConfigFor(state.activeBrand)}
  function selectedBrandProjects(){var ids=activeBrandConfig().projectIds;return monitoringProjects.filter(function(p){return ids.indexOf(p.id)>-1})}
  function getFilteredMonitorProjects(){return monitoringProjects.filter(function(p){var keyword=(p.name+p.brand+p.keywords+p.platforms.join("")).toLowerCase(),brandMatch=state.projectBrandScope==="all"||p.brandKey===state.activeBrand;return brandMatch&&(!state.projectKeyword||keyword.indexOf(state.projectKeyword.toLowerCase())>-1)&&(state.projectScene==="all"||p.scene===state.projectScene)&&(state.projectStatus==="all"||p.status===state.projectStatus)})}
  function projectMaxPage(){return Math.max(1,Math.ceil(getFilteredMonitorProjects().length/state.projectPageSize))}
  function projectPageRows(){var max=projectMaxPage();if(state.projectPage>max)state.projectPage=max;var start=(state.projectPage-1)*state.projectPageSize;return getFilteredMonitorProjects().slice(start,start+state.projectPageSize)}
  function projectCountText(){return"共找到 "+getFilteredMonitorProjects().length+" 个监测项目 · "+activeBrand().name+"已接入 "+activeBrandConfig().projectIds.length+" 个"}
  function projectPageText(){return"第 "+state.projectPage+" / "+projectMaxPage()+" 页"}
  function projectRowsHtml(){var rows=projectPageRows(),selectedIds=activeBrandConfig().projectIds;if(!rows.length)return'<tr><td colspan="7"><div class="tail-project-empty">没有找到符合条件的监测项目</div></td></tr>';return rows.map(function(p){var selected=selectedIds.indexOf(p.id)>-1;return'<tr class="'+(selected?'is-selected':'')+'"><td><div class="tail-project-name"><strong>'+esc(p.name)+'</strong><span>'+esc(p.keywords)+'</span></div></td><td><span class="tail-tag">'+p.brand+'</span></td><td><span class="tail-tag">'+p.sceneLabel+'</span><span class="tail-row-meta">'+p.statusLabel+'</span></td><td>'+p.platforms.slice(0,3).map(function(x){return'<span class="tail-tag">'+esc(x)+'</span>'}).join(" ")+'</td><td><strong>'+format(p.dataCount)+'</strong><span class="tail-row-meta">今日 +'+format(p.today)+'</span></td><td>'+p.updated+'</td><td><button class="tail-button '+(selected?'':'is-primary')+'" data-tail-project-select="'+p.id+'">'+(selected?'已添加 · 移除':'添加')+'</button></td></tr>'}).join("")}
  function renderProjectPickerResults(){var body=qs("#tailProjectTableBody");if(!body)return;body.innerHTML=projectRowsHtml();var count=qs("#tailProjectCount"),pageText=qs("#tailProjectPage");if(count)count.textContent=projectCountText();if(pageText)pageText.textContent=projectPageText();var prev=qs('[data-tail-action="project-prev"]'),next=qs('[data-tail-action="project-next"]');if(prev)prev.disabled=state.projectPage===1;if(next)next.disabled=state.projectPage>=projectMaxPage()}
  function toggleMonitorProject(id){var ids=activeBrandConfig().projectIds,index=ids.indexOf(id);if(index>-1){ids.splice(index,1);toast("已从"+activeBrand().name+"移除该项目")}else{ids.push(id);toast("监测项目已添加到"+activeBrand().name+"数据源")}persist();renderProjectPickerResults()}
  function toggleBrandArray(field,value,checked){var rows=activeBrandConfig()[field]||[],index=rows.indexOf(value);if(checked&&index<0)rows.push(value);if(!checked&&index>-1)rows.splice(index,1)}
  function insertExpressionToken(field,token){var config=activeBrandConfig(),textarea=qs('[data-brand-field="'+field+'"]'),current=textarea?textarea.value:config[field]||"";config[field]=(current+(current&&!/\s$/.test(current)?" ":"")+token).trim();if(textarea){textarea.value=config[field];textarea.focus()}}

  function renderTasks(){var rows=visibleTasks(),filtered=brandFilteredTasks(),today=filtered.filter(todayTask);qs("#tailContent").innerHTML=brandFilterBar("tasks")+'<section class="tail-kpis">'+[["今日下发",today.length,"所选品牌任务"],["待评论审核",today.filter(function(t){return t.status==="vendor_submitted"||t.status==="internal_review"}).length,"人工与AI评论"],["供应商执行中",today.filter(function(t){return t.status==="export_ready"||t.status==="vendor_executing"}).length,"导出与下发"],["待验收",today.filter(function(t){return t.status==="evidence_review"}).length,"智能校验后确认"],["今日完成",today.filter(function(t){return t.status==="completed"}).length,"结果已归档"]].map(kpi).join("")+'</section>'+todayCompletionStructure(today)+'<section class="tail-panel"><header class="tail-panel-head"><div class="tail-vendor-tabs"><button class="'+(state.vendor==="all"?"is-active":"")+'" data-vendor="all">全部供应商</button>'+suppliers.map(function(v){return'<button class="'+(state.vendor===v?"is-active":"")+'" data-vendor="'+v+'">'+v+'</button>'}).join("")+'</div><div class="tail-panel-actions"><select data-tail-filter="taskScope"><option value="today" '+(state.taskScope==="today"?"selected":"")+'>当天任务</option><option value="history" '+(state.taskScope==="history"?"selected":"")+'>历史全部任务</option></select></div></header><div class="tail-filter-summary"><div class="tail-state-tabs">'+taskStateTabs().map(function(s){return'<button class="'+(state.taskStatus===s[0]?"is-active":"")+'" data-task-status="'+s[0]+'">'+s[1]+'</button>'}).join("")+'</div><div class="tail-panel-actions"><button class="tail-icon-button tail-column-gear" title="设置台账展示字段" aria-label="设置台账展示字段" data-tail-action="open-column-settings">⚙</button><button class="tail-button" data-tail-action="export-task-ledger">导出任务台账</button></div></div><div class="tail-table-wrap tail-ledger-wrap">'+renderTaskTable(rows,true)+'</div><footer class="tail-panel-foot"><span>共 '+rows.length+' 个任务 · 当前展示 '+state.taskColumns.length+' 个内容字段</span></footer></section>'}
  function renderTaskRangeControl(){var actions=qs("#tailContent .tail-panel-head .tail-panel-actions");if(!actions)return;actions.className="tail-task-range";actions.innerHTML='<span>任务时间</span><label><em>开始</em><input id="tailTaskStart" type="datetime-local" value="'+esc(state.taskStart)+'"></label><b>至</b><label><em>结束</em><input id="tailTaskEnd" type="datetime-local" value="'+esc(state.taskEnd)+'"></label>'}
  function renderChart(){var vals=[3,5,4,6,2,5,4];return'<section class="tail-chart"><h2>近7日任务完成趋势</h2><p>下发任务与完成任务按天对比</p><div class="tail-bars">'+vals.map(function(v,i){return'<div class="tail-bar"><i style="--height:'+(v*14)+'px"></i><span>08/'+(8+i)+'</span></div>'}).join("")+'</div><div class="tail-chart-legend"><span>累计下发 <b>29</b></span><span>累计完成 <b>23</b></span><span>完成率 <b>79%</b></span></div></section>'}
  function renderTaskTable(rows,internal){if(!rows.length)return'<div class="tail-empty">当前品牌和筛选条件下没有任务</div>';if(!internal)return renderVendorTaskTable(rows);var columns=taskContentColumns.filter(function(col){return state.taskColumns.indexOf(col.id)>-1});return'<table class="tail-table tail-ledger-table"><thead><tr><th>任务编号</th><th>供应商</th><th>撰写方式</th>'+columns.map(function(col){return'<th title="'+esc(col.sample)+'">'+col.label+'</th>'}).join("")+'<th>评论进度</th><th>执行佐证</th><th>当前状态</th><th>下发时间</th><th>操作</th></tr></thead><tbody>'+rows.map(function(t){var p=findPost(t.postId);if(!p)return"";return'<tr class="'+(t.status==="returned"||t.status==="vendor_rejected"?"is-returned":"")+'"><td><strong>'+t.id.toUpperCase()+'</strong></td><td>'+esc(t.vendor)+'</td><td><span class="tail-tag">'+(t.mode==="ai"?"AI撰写":"人工撰写")+'</span></td>'+columns.map(function(col){return'<td class="tail-ledger-col is-'+col.id+'">'+taskColumnCell(col.id,p)+'</td>'}).join("")+'<td>'+t.comments.filter(function(c){return c.status==="approved"}).length+'/'+t.commentCount+' 条通过</td><td>'+evidenceSummary(t)+'</td><td>'+taskStatus(t.status)+(t.vendorRejectReason?'<span class="tail-row-meta tail-reject-reason">'+esc(t.vendorRejectReason)+'</span>':"")+'</td><td>'+t.created+'</td><td><div class="tail-row-actions"><button class="tail-button" data-tail-action="'+(internal?"open-internal-task":"open-vendor-task")+'" data-task-id="'+t.id+'">查看</button>'+(internal&&t.status==="vendor_rejected"?'<button class="tail-button is-danger" data-tail-action="accept-vendor-rejection" data-task-id="'+t.id+'">删除任务</button>':"")+'</div></td></tr>'}).join("")+'</tbody></table>'}
  function renderVendorTaskTable(rows){if(!rows.length)return'<div class="tail-empty">当前品牌和筛选条件下没有本公司的任务</div>';return'<table class="tail-table tail-vendor-work-table"><thead><tr><th>任务编号</th><th>接收时间</th><th>品牌 / 车型</th><th>主贴内容</th><th>撰写方式</th><th>任务要求</th><th>工作进度</th><th>当前状态</th><th>操作</th></tr></thead><tbody>'+rows.map(function(t){var p=findPost(t.postId);if(!p)return"";var approved=t.comments.filter(function(c){return c.status==="approved"}).length,progress=t.status==="vendor_pending"?"尚未接收":t.status==="vendor_writing"||t.status==="returned"?"已填写 "+t.comments.filter(function(c){return c.text}).length+" / "+t.commentCount+" 条":t.status==="vendor_submitted"||t.status==="internal_review"?"已提交 "+t.commentCount+" 条":t.status==="completed"?"已验收完成":approved+" / "+t.commentCount+" 条已审核",actionLabel=t.status==="vendor_pending"?"处理任务":t.status==="vendor_writing"||t.status==="returned"?"撰写评论":t.status==="export_ready"?"开始执行":t.status==="vendor_executing"?"上传佐证":"查看任务";return'<tr class="'+(t.status==="returned"||t.status==="vendor_rejected"?'is-returned':'')+'"><td><strong>'+t.id.toUpperCase()+'</strong></td><td>'+t.created+'</td><td><strong>'+esc(p.brand)+'</strong><span class="tail-row-meta">'+esc(p.model)+'</span></td><td class="tail-vendor-source-cell"><strong>'+esc(p.title)+'</strong><span>'+esc(p.platform)+' · '+esc(p.media)+'</span></td><td><span class="tail-tag">'+(t.mode==="ai"?'AI已撰写':'人工撰写')+'</span></td><td class="tail-vendor-requirement-cell"><strong>需完成 '+t.commentCount+' 条</strong><span>'+esc(t.requirement)+'</span></td><td>'+progress+(t.evidence.length?'<span class="tail-row-meta">佐证 '+t.evidence.length+' 张</span>':"")+'</td><td>'+taskStatus(t.status)+(t.vendorRejectReason?'<span class="tail-row-meta tail-reject-reason">'+esc(t.vendorRejectReason)+'</span>':"")+'</td><td><button class="tail-button '+(t.status==="vendor_pending"||t.status==="vendor_writing"||t.status==="returned"||t.status==="vendor_executing"?'is-primary':'')+'" data-tail-action="open-vendor-task" data-task-id="'+t.id+'">'+actionLabel+'</button></td></tr>'}).join("")+'</tbody></table>'}
  function todayCompletionStructure(rows){return'<section class="tail-completion-structure"><div><h2>今日完成结构</h2><p>当前所选品牌按供应商统计下发与完成情况</p></div><div class="tail-completion-suppliers">'+suppliers.map(function(v){var all=rows.filter(function(t){return t.vendor===v}).length,done=rows.filter(function(t){return t.vendor===v&&t.status==="completed"}).length;return'<article><span>'+v+'</span><strong>'+done+' / '+all+'</strong><em>完成率 '+percent(done,all)+'</em></article>'}).join("")+'</div></section>'}
