  function taskColumnCell(id,p){var value={publish:p.publish,brand:p.brand,model:p.model,tone:p.tone,category:p.category,title:p.title,excerpt:p.excerpt,type:p.type,platform:p.platform,platformLevel:p.platformLevel,author:p.author,followers:format(p.followers),mediaLevel:p.mediaLevel,likes:format(p.likes),comments:format(p.comments),reposts:format(p.reposts),health:p.health,linkLevel:p.linkLevel,mentionType:p.mentionType}[id];if(id==="link")return'<a class="tail-ledger-link" href="'+esc(p.url)+'" target="_blank" rel="noopener">打开链接</a>';return'<span title="'+esc(value)+'">'+esc(value)+'</span>'}
