  function renderInternalDetail(){var t=currentTask(),p=t&&findPost(t.postId);if(!t||!p){qs("#tailContent").innerHTML='<div class="tail-empty">未找到任务</div>';return}qs("#tailContent").innerHTML=stepper(t)+'<section class="tail-detail-stack">'+sourceTaskPanel(t,p)+'<section class="tail-block tail-review-block"><div class="tail-block-head tail-review-head"><div><h2>评论内容审核</h2><p class="tail-block-subtitle">'+(t.mode==="ai"?"AI生成评论可人工修改、重新生成或批量审核":"供应商提交评论可逐条或批量审核")+'</p></div>'+internalActions(t)+'</div><div class="tail-comment-list tail-review-grid">'+t.comments.map(function(c,i){return commentInternal(c,i,t)}).join("")+'</div></section>'+(t.evidence.length?'<section class="tail-block"><div class="tail-block-head"><div><h2>执行佐证</h2><p class="tail-block-subtitle">按维护前、72小时看管、维护处置和举报操作四类核对材料</p></div>'+taskStatus(t.status)+'</div>'+evidenceBlock(t)+'</section>':"")+'</section>'}
  function commentInternal(c,i,t){var selected=state.reviewSelected.indexOf(c.id)>-1;return'<article class="tail-comment tail-review-comment '+(selected?"is-selected":"")+'"><div class="tail-comment-head"><label class="tail-comment-select"><input type="checkbox" data-review-comment="'+c.id+'" '+(selected?"checked":"")+'><strong>评论 '+(i+1)+'</strong></label>'+commentStatus(c.status)+'</div>'+(t.mode==="ai"?'<textarea class="tail-comment-editor" data-edit-comment="'+c.id+'">'+esc(c.text)+'</textarea>':'<p>'+esc(c.text)+'</p>')+(c.rewriteRequirement?'<div class="tail-comment-note">重写要求：'+esc(c.rewriteRequirement)+'</div>':"")+'<div class="tail-inline-actions tail-comment-actions">'+(c.status!=="approved"?'<button class="tail-button" data-tail-action="approve-comment" data-comment-id="'+c.id+'">通过</button>':"")+(t.mode==="ai"?'<button class="tail-button" data-tail-action="save-ai-comment" data-comment-id="'+c.id+'">保存修改</button><button class="tail-button is-accent" data-tail-action="rewrite-ai-comment" data-comment-id="'+c.id+'">AI重新写</button>':"")+'</div></article>'}
  function internalActions(t){if(t.status==="vendor_rejected")return'<div class="tail-review-actions"><span class="tail-return-inline">供应商退回：'+esc(t.vendorRejectReason)+'</span><button class="tail-button is-danger" data-tail-action="accept-vendor-rejection" data-task-id="'+t.id+'">确认并删除任务与主贴</button></div>';if(t.status==="vendor_submitted"||t.status==="internal_review"){var allSelected=t.comments.length&&state.reviewSelected.length===t.comments.length,allApproved=t.comments.length&&t.comments.every(function(c){return c.status==="approved"});return'<div class="tail-review-actions"><label class="tail-review-select-all"><input id="tailReviewSelectAll" type="checkbox" '+(allSelected?"checked":"")+'><span>全选</span></label><button class="tail-button" data-tail-action="batch-approve-comments" '+(state.reviewSelected.length?"":"disabled")+'>通过所选</button><button class="tail-button is-danger" data-tail-action="batch-reject-comments" '+(state.reviewSelected.length?"":"disabled")+'>打回所选</button><button class="tail-button" data-tail-action="reject-all-comments">全部打回</button><button class="tail-button is-primary" data-tail-action="approve-all-comments">全部通过</button>'+(t.mode==="ai"?'<button class="tail-button is-primary" data-tail-action="send-ai-to-vendor" '+(allApproved?"":"disabled")+'>发送供应商执行</button>':"")+'</div>'}if(t.status==="evidence_review")return'<div class="tail-review-actions"><button class="tail-button is-danger" data-tail-action="reject-evidence">退回补充佐证</button><button class="tail-button is-primary" data-tail-action="accept-completion">人工确认完成</button></div>';return'<div class="tail-review-actions">'+taskStatus(t.status)+'</div>'}
  function sourceTaskPanel(t,p){return'<section class="tail-block tail-source-task-panel"><button class="tail-source-task-toggle" data-tail-action="toggle-detail-info"><span><strong>主贴原文与任务信息</strong><em>'+esc(p.brand)+' · '+esc(p.model)+' · '+esc(t.vendor)+' · '+stripTags(taskStatus(t.status))+'</em></span><b>'+(state.detailInfoExpanded?'收起':'展开查看')+'</b></button>'+(state.detailInfoExpanded?'<div class="tail-source-task-body"><section>'+sourceBlock(p)+'</section><section>'+taskSummary(t,p)+'</section></div>':'')+'</section>'}
  function toggleReviewSelected(id,checked){var index=state.reviewSelected.indexOf(id);if(checked&&index<0)state.reviewSelected.push(id);if(!checked&&index>-1)state.reviewSelected.splice(index,1);renderInternalDetail()}
  function toggleTaskColumn(id,checked){var index=state.taskColumns.indexOf(id);if(checked&&index<0)state.taskColumns.push(id);if(!checked&&index>-1)state.taskColumns.splice(index,1);persist();var count=qs("#tailColumnSelectedCount");if(count)count.textContent=state.taskColumns.length+" / "+taskContentColumns.length+" 个字段"}
  function stripTags(html){var div=document.createElement("div");div.innerHTML=html;return div.textContent||""}

  function renderVendorList(){var rows=visibleVendorTasks(),scoped=tasks.filter(function(t){return t.vendor==="星河传播"&&brandSelected(findPost(t.postId))}),today=scoped.filter(todayTask);qs("#tailContent").innerHTML=brandFilterBar("vendor")+'<section class="tail-kpis tail-vendor-kpis">'+[["今日收到",today.length,"所选品牌任务"],["待接收",scoped.filter(function(t){return t.status==="vendor_pending"}).length,"接收或退回"],["待撰写",scoped.filter(function(t){return t.status==="vendor_writing"||t.status==="returned"}).length,"完成人工评论"],["等待审核",scoped.filter(function(t){return t.status==="vendor_submitted"||t.status==="internal_review"}).length,"内部处理中"],["待执行",scoped.filter(function(t){return t.status==="export_ready"||t.status==="vendor_executing"||t.status==="evidence_review"}).length,"发布及上传佐证"],["已完成",scoped.filter(function(t){return t.status==="completed"}).length,"内部已验收"]].map(kpi).join("")+'</section><section class="tail-panel"><header class="tail-panel-head"><div class="tail-state-tabs">'+vendorStateTabs().map(function(s){return'<button class="'+(state.vendorStatus===s[0]?'is-active':'')+'" data-vendor-status="'+s[0]+'">'+s[1]+'</button>'}).join("")+'</div><button class="tail-button" data-tail-action="vendor-export-all">导出可执行任务</button></header><div class="tail-toolbar tail-vendor-toolbar"><label class="tail-field"><span>关键词</span><input id="tailKeyword" value="'+esc(state.keyword)+'" placeholder="搜索任务、标题、品牌或车型"></label>'+selectField("taskScope","任务日期",[["today","今天"],["history","历史全部"]],state.taskScope)+'<div class="tail-toolbar-note">这里仅展示供应商完成工作需要的任务信息</div></div><div class="tail-table-wrap">'+renderVendorTaskTable(rows)+'</div><footer class="tail-panel-foot"><span>共 '+rows.length+' 个任务 · 按接收、撰写、审核、执行和完成状态推进</span></footer></section>'}

  function renderVendorDetail(){var t=currentTask(),p=t&&findPost(t.postId);if(!t||t.vendor!=="星河传播"){qs("#tailContent").innerHTML='<div class="tail-empty">未找到本公司的任务</div>';return}qs("#tailContent").innerHTML=stepper(t)+'<div class="tail-detail-stack tail-vendor-detail-stack">'+sourceTaskPanel(t,p)+'<section class="tail-block"><div class="tail-block-head"><div><h2>评论内容</h2><p class="tail-block-subtitle">'+(t.mode==="ai"?'AI评论已随任务下发，确认内容后直接进入执行。':'按任务要求完成 '+t.commentCount+' 条评论并提交内部审核。')+'</p></div><span class="tail-tag">'+(t.mode==="ai"?'AI撰写':'供应商人工撰写')+'</span></div>'+vendorCommentArea(t)+'</section><section class="tail-block">'+vendorExecution(t)+'</section></div>'}
  function vendorCommentArea(t){if(t.status==="vendor_rejected")return'<section class="tail-returned-banner"><div><strong>任务已退回内部</strong><span>内部人员将根据退回理由处理任务与主贴。</span></div><p>'+esc(t.vendorRejectReason)+'</p></section>';if(t.status==="vendor_pending")return'<section class="tail-vendor-accept"><div><strong>请确认是否接收本任务</strong><span>接收前可以拒绝并说明原因；一旦接收，任务进入执行流程，不再允许退回。</span></div><div class="tail-inline-actions"><button class="tail-button is-danger" data-tail-action="vendor-reject-task">拒绝并退回</button><button class="tail-button is-primary" data-tail-action="accept-vendor-task">接收任务</button></div></section>';if(t.status==="vendor_writing"||t.status==="returned"){return'<div class="tail-vendor-comment-top">'+(t.status==="returned"?'<section class="tail-returned-banner"><div><strong>审核未通过，请重新填写</strong><span>内部已将部分评论打回，修改后再次提交审核。</span></div><b>重新提交</b><p>'+esc(t.feedback||"请根据审核意见修改评论内容。")+'</p></section>':'<div class="tail-writing-tip"><strong>手写评论内容</strong><span>请逐条填写 '+t.commentCount+' 条评论，全部填写后提交内部审核。</span></div>')+'</div><div class="tail-comment-list tail-vendor-writing-list">'+Array.from({length:t.commentCount},function(_,i){var c=t.comments[i];return'<label class="tail-field tail-rewrite-field '+(c&&c.status==="rejected"?"is-rejected":"")+'"><span>评论 '+(i+1)+(c&&c.status==="rejected"?" · 需重写":"")+'</span><textarea data-vendor-comment="'+i+'" placeholder="在这里手写第 '+(i+1)+' 条评论内容">'+esc(c?c.text:"")+'</textarea></label>'}).join("")+'</div><button class="tail-button is-primary" style="margin-top:10px" data-tail-action="submit-vendor-comments">'+(t.status==="returned"?"重新提交内部审核":"提交评论审核")+'</button>'}return'<div class="tail-comment-list">'+t.comments.map(function(c,i){return'<article class="tail-comment"><div class="tail-comment-head"><strong>评论 '+(i+1)+'</strong><span class="tail-status is-ready">已审核</span></div><p>'+esc(c.text)+'</p></article>'}).join("")+'</div>'}
  function vendorExecution(t){var html='<div class="tail-block-head"><div><h2>执行操作</h2><p class="tail-block-subtitle">评论审核通过后执行发布，并按四类材料上传结果。</p></div>'+taskStatus(t.status)+'</div>';if(t.status==="vendor_pending")html+='<p class="tail-muted">请先在上方确认接收任务，接收后系统会开放对应工作步骤。</p>';else if(t.status==="export_ready")html+='<p class="tail-muted">评论已审核，可导出主贴与评论内容并使用外部系统执行。</p><div class="tail-inline-actions" style="margin-top:10px"><button class="tail-button" data-tail-action="vendor-export-task">导出Excel</button><button class="tail-button is-primary" data-tail-action="start-vendor-execution">开始执行</button></div>';else if(t.status==="vendor_executing")html+='<div class="tail-evidence-intro"><strong>上传执行结果截图</strong><span>维护前和72小时看管各1张；单评/多评处置截图按实际评论逐条上传；举报操作需上传多张记录。</span></div><div class="tail-upload-grid">'+evidenceUploadCard("before","1. 维护前原始截图","证明执行前的主贴与评论区原始状态","固定1张")+evidenceUploadCard("after72","2. 72小时看管监控截图","维护后持续看管72小时的最终状态","固定1张")+evidenceUploadCard("comments","3. 单评 / 多评维护处置截图","每条维护评论对应上传处置结果，可达几十张","至少"+t.commentCount+"张")+evidenceUploadCard("reports","4. 举报操作截图","举报提交、受理及平台反馈等过程材料","多张")+'</div><div class="tail-evidence-submit"><span>已上传 '+totalUploadCount()+' 张，提交后进入智能校验与内部验收。</span><button class="tail-button is-primary" data-tail-action="submit-evidence">提交全部执行佐证</button></div>';else if(t.status==="evidence_review")html+='<div class="tail-ai-result"><strong>四类佐证已提交</strong>内部智能校验与人工验收中，请等待结果。</div>'+evidenceBlock(t);else if(t.status==="completed")html+='<div class="tail-ai-result"><strong>任务已完成</strong>内部已经验收，任务材料与评论结果已归档。</div>'+evidenceBlock(t);else if(t.status==="vendor_rejected")html+='<div class="tail-ai-result is-rejected"><strong>任务已退回</strong>'+esc(t.vendorRejectReason)+'</div>';else html+='<p class="tail-muted">请先完成评论撰写并等待内部审核。</p>';return html}
  function evidenceUploadCard(key,title,desc,requirement){var rows=state.uploads[key]||[],multiple=key!=="before"&&key!=="after72";return'<article class="tail-upload-card '+(rows.length?'is-filled':'')+'"><div class="tail-upload-card-head"><div><strong>'+title+'</strong><span>'+desc+'</span></div><b>'+rows.length+' 张</b></div><div class="tail-upload-actions"><label class="tail-upload">'+(multiple?'添加1张':'选择本地图片')+'<input type="file" accept="image/*" data-upload-mode="single" data-evidence-upload="'+key+'"></label>'+(multiple?'<label class="tail-upload is-batch">批量选择<input type="file" accept="image/*" multiple data-upload-mode="batch" data-evidence-upload="'+key+'"></label>':'')+'</div><div class="tail-upload-requirement">'+requirement+(multiple?' · 可多次添加，已选图片不会被覆盖':'')+'</div>'+files(rows,key)+'</article>'}
  function totalUploadCount(){return Object.keys(state.uploads).reduce(function(sum,key){return sum+(state.uploads[key]||[]).length},0)}

  function handle(action,target){var pid=target.getAttribute("data-post-id"),projectId=target.getAttribute("data-project-id"),tid=target.getAttribute("data-task-id"),cid=target.getAttribute("data-comment-id"),brandId=target.getAttribute("data-brand-id"),p=pid&&findPost(pid),t=tid&&findTask(tid)||currentTask();
    if(action==="close-modal"){closeModal();return}
    if(action==="open-add-posts"){openManualPostModal();return}
    if(action==="switch-manual-post-mode"){state.manualPostMode=target.getAttribute("data-mode");renderModal();return}
    if(action==="add-manual-link-row"){state.manualUrls.push("");renderModal();return}
    if(action==="remove-manual-link-row"){var manualIndex=Number(target.getAttribute("data-url-index"));if(state.manualUrls.length>1)state.manualUrls.splice(manualIndex,1);renderModal();return}
    if(action==="download-post-template"){downloadPostTemplate();return}
    if(action==="confirm-add-posts"){confirmAddPosts();return}
    if(action==="open-brand-manager"){openModal("brand-manager");return}
    if(action==="open-brand-edit"){openModal("brand-edit",brandId||"");return}
    if(action==="save-brand-definition"){saveBrandDefinition();return}
    if(action==="request-delete-brand"){openModal("brand-delete",brandId);return}
    if(action==="confirm-delete-brand"){deleteBrandDefinition(state.modal.id);return}
    if(action==="remove-upload"){var uploadKey=target.getAttribute("data-upload-category"),uploadIndex=Number(target.getAttribute("data-upload-index"));if(state.uploads[uploadKey])state.uploads[uploadKey].splice(uploadIndex,1);render();toast("已移除图片");return}
    if(action==="reset-demo-data"){try{localStorage.removeItem(storageKey);localStorage.removeItem("tail-current-task")}catch(e){}location.reload();return}
    if(action==="configure-tab"){if(!tabFilters[state.tab]){toast("请先选择一个具体时间段");return}openFilterModal(state.tab);return}
    if(action==="configure-specific-tab"){openFilterModal(target.getAttribute("data-tab-id"));return}
    if(action==="open-brand-project-picker"){state.projectKeyword="";state.projectScene="all";state.projectStatus="running";state.projectBrandScope="current";state.projectPage=1;openModal("brand-projects");return}
    if(action==="remove-brand-project"){var ids=activeBrandConfig().projectIds,index=ids.indexOf(projectId);if(index>-1)ids.splice(index,1);persist();render();toast("已从"+activeBrand().name+"数据源中移除");return}
    if(action==="reset-project-filter"){state.projectKeyword="";state.projectScene="all";state.projectStatus="running";state.projectBrandScope="current";state.projectPage=1;var search=qs("#tailProjectSearch"),scene=qs("#tailProjectScene"),status=qs("#tailProjectStatus"),scope=qs("#tailProjectBrandScope");if(search)search.value="";if(scene)scene.value="all";if(status)status.value="running";if(scope)scope.value="current";renderProjectPickerResults();return}
    if(action==="project-prev"){state.projectPage=Math.max(1,state.projectPage-1);renderProjectPickerResults();return}
    if(action==="project-next"){state.projectPage=Math.min(projectMaxPage(),state.projectPage+1);renderProjectPickerResults();return}
    if(action==="add-time-tab"){openModal("add-tab");return}
    if(action==="assign-one"){state.selected=[pid];state.assignMode="human";openModal("assign");return}
    if(action==="batch-assign"){if(!state.selected.length){toast("请先选择主贴");return}state.assignMode="human";openModal("assign");return}
    if(action==="delete-one"){deletePosts([pid]);return}
    if(action==="batch-delete"){if(!state.selected.length){toast("请先选择主贴");return}deletePosts(state.selected);return}
    if(action==="restore-post"){p.deleted=false;p.deletedAt="";persist();render();toast("信息已恢复到原时间段");return}
    if(action==="open-original"){p.read=true;persist();window.open(p.url||"https://example.com/source","_blank","noopener");toast("已打开原文");return}
    if(action==="confirm-assign"){confirmAssign();return}
    if(action==="save-tab-filter"){saveTabFilter();return}
    if(action==="create-time-tab"){createTimeTab();return}
    if(action==="save-settings"){persist();toast(activeBrand().name+"配置已保存并启用");return}
    if(action==="view-post-task"){var pt=tasks.filter(function(x){return x.postId===pid})[0];if(pt)openInternalTask(pt.id);return}
    if(action==="open-internal-task"){openInternalTask(tid);return}
    if(action==="open-vendor-task"){openVendorTask(tid);return}
    if(action==="toggle-detail-info"){state.detailInfoExpanded=!state.detailInfoExpanded;if(page==="vendor-detail")renderVendorDetail();else renderInternalDetail();return}
    if(action==="open-column-settings"){openModal("column-settings");return}
    if(action==="save-ai-comment"){var edited=findComment(t,cid),editor=qs('[data-edit-comment="'+cid+'"]');if(!editor||!editor.value.trim()){toast("评论内容不能为空");return}edited.text=editor.value.trim();edited.status="pending";persist();renderInternalDetail();toast("人工修改已保存");return}
    if(action==="batch-approve-comments"){state.reviewSelected.forEach(function(id){var item=findComment(t,id);if(item)item.status="approved"});state.reviewSelected=[];persist();renderInternalDetail();toast("所选评论已通过");return}
    if(action==="batch-reject-comments"){if(!state.reviewSelected.length){toast("请先勾选评论");return}openModal("batch-reject",t.id,state.reviewSelected.join(","));return}
    if(action==="reject-one-comment"){openModal("batch-reject",t.id,cid);return}
    if(action==="reject-all-comments"){openModal("batch-reject",t.id,t.comments.map(function(c){return c.id}).join(","));return}
    if(action==="confirm-batch-reject"){var reason=qs("#tailBatchRejectReason").value.trim(),idsToReject=String(state.modal.extra||"").split(",").filter(Boolean);if(!reason){toast("请填写打回重写要求");return}idsToReject.forEach(function(id){var item=findComment(t,id);if(item&&item.status!=="approved"){item.status="rejected";item.rewriteRequirement=reason}});if(t.mode==="human"){t.status="returned";t.feedback=reason}state.reviewSelected=[];persist();closeModal();render();toast(t.mode==="human"?"所选评论已打回供应商重写，已通过评论保持不变":"所选AI评论已标记重写");return}
    if(action==="approve-all-comments"){t.comments.forEach(function(c){c.status="approved"});state.reviewSelected=[];if(t.mode==="human")t.status="export_ready";persist();render();toast(t.mode==="human"?"评论全部通过，供应商可以执行":"AI评论已全部通过，可发送供应商执行");return}
    if(action==="accept-vendor-task"){t.status=t.mode==="ai"?"export_ready":"vendor_writing";t.vendorRejectReason="";persist();render();toast(t.mode==="ai"?"任务已接收，可以开始执行":"任务已接收，请按要求撰写评论");return}
    if(action==="vendor-reject-task"){if(t.status!=="vendor_pending"){toast("任务接收后不可退回");return}openModal("vendor-reject",t.id);return}
    if(action==="confirm-vendor-reject"){var rejectReason=qs("#tailVendorRejectReason").value.trim();if(!rejectReason){toast("请填写退回理由");return}t.status="vendor_rejected";t.vendorRejectReason=rejectReason;persist();closeModal();render();toast("任务已退回内部处理");return}
    if(action==="accept-vendor-rejection"){var taskIndex=tasks.indexOf(t),postToDelete=findPost(t.postId),postIndex=posts.indexOf(postToDelete);if(taskIndex>-1)tasks.splice(taskIndex,1);if(postIndex>-1)posts.splice(postIndex,1);persist();if(page==="task-detail")location.href="./module-tail-tasks.html";else render();toast("任务与对应主贴已删除");return}
    if(action==="approve-comment"){var c=findComment(t,cid);c.status="approved";persist();render();toast("评论已通过");return}
    if(action==="reject-human-comments"){openModal("reject-comments",t.id);return}
    if(action==="confirm-reject-comments"){t.feedback=qs("#tailRejectReason").value.trim();if(!t.feedback){toast("请填写打回要求");return}t.status="returned";t.comments.forEach(function(c){if(c.status!=="approved")c.status="rejected"});persist();closeModal();render();toast("已打回供应商重新撰写");return}
    if(action==="rewrite-ai-comment"){openModal("rewrite-ai",t.id,cid);return}
    if(action==="confirm-rewrite-ai"){rewriteAiComment();return}
    if(action==="send-ai-to-vendor"){if(t.comments.some(function(c){return c.status!=="approved"})){toast("请先通过全部AI评论");return}t.status="vendor_pending";persist();render();toast("AI评论已发送供应商，等待接收");return}
    if(action==="reject-evidence"){t.status="vendor_executing";t.aiValidation=null;state.uploads=emptyUploads();persist();render();toast("已退回供应商补充四类佐证");return}
    if(action==="accept-completion"){t.status="completed";persist();render();toast("任务已人工确认完成并归档");return}
    if(action==="submit-vendor-comments"){submitVendorComments(t);return}
    if(action==="vendor-export-task"){exportTask(t);return}
    if(action==="vendor-export-all"){exportTasks(tasks.filter(function(x){return x.vendor==="星河传播"&&x.status==="export_ready"}));return}
    if(action==="start-vendor-execution"){t.status="vendor_executing";state.uploads=emptyUploads();persist();render();toast("任务已进入执行中，请按四类上传执行佐证");return}
    if(action==="submit-evidence"){var needed=t.commentCount||t.comments.length;if(state.uploads.before.length!==1){toast("维护前原始截图需上传1张");return}if(state.uploads.after72.length!==1){toast("72小时看管监控截图需上传1张");return}if(state.uploads.comments.length<needed){toast("单评 / 多评维护处置截图至少需与"+needed+"条评论逐条对应");return}if(state.uploads.reports.length<2){toast("举报操作截图需上传多张，至少2张");return}t.evidence=[].concat(prefixFiles("维护前原始截图",state.uploads.before),prefixFiles("72小时看管监控截图",state.uploads.after72),prefixFiles("单评 / 多评维护处置截图",state.uploads.comments),prefixFiles("举报操作截图",state.uploads.reports));t.status="evidence_review";t.aiValidation={result:"passed",score:95,summary:"四类材料完整：维护前后状态可对比，"+needed+"条评论均有处置截图，举报操作记录完整。"};state.uploads=emptyUploads();persist();render();toast("四类佐证已提交，智能校验完成并等待内部验收");return}
    if(action==="download-report"){openModal("report-range");return}
    if(action==="confirm-range-report"){downloadRangeReport();return}
    if(action==="start-next-round"){startNextRound(t);return}
    if(action==="export-task-ledger"){exportTasks(visibleTasks());return}
  }

  function openModal(type,id,extra){state.modal={type:type,id:id||"",extra:extra||""};renderModal();if(type==="assign")enhanceAssignModal();qs("#tailModalLayer").hidden=false}
  function openManualPostModal(){var firstSelected=state.selectedBrands[0]||tailBrands[0].id;state.manualPostMode="single";state.manualPostBrand=findBrand(firstSelected)?firstSelected:tailBrands[0].id;state.manualUrls=[""];state.manualFileName="";state.manualBatchUrls=[];openModal("add-posts")}
  function openFilterModal(id){if(!tabFilters[id]){toast("未找到该时间段的筛选方案");return}openModal("filter",id)}
  function closeModal(){var type=state.modal&&state.modal.type,refreshSettings=type==="brand-projects",refreshTasks=type==="column-settings",refreshBrands=type&&type.indexOf("brand-")===0;state.modal=null;qs("#tailModalLayer").hidden=true;qs("#tailModal").innerHTML="";if(refreshBrands)render();else if(refreshSettings&&page==="settings")renderSettings();else if(refreshTasks&&page==="tasks")renderTasks()}
  function renderModal(){if(!state.modal)return;var m=qs("#tailModal");m.className="tail-modal";if(state.modal.type!=="assign")m.classList.add("is-medium");if(state.modal.type==="assign")m.classList.add("is-assign");if(state.modal.type==="add-posts")m.classList.add("is-add-posts");if(state.modal.type==="brand-projects")m.classList.add("is-project-picker");if(state.modal.type==="brand-manager")m.classList.add("is-brand-manager");if(state.modal.type==="assign")m.innerHTML=assignModal();if(state.modal.type==="add-posts")m.innerHTML=manualPostModal();if(state.modal.type==="filter")m.innerHTML=filterModal(state.modal.id);if(state.modal.type==="add-tab")m.innerHTML=addTabModal();if(state.modal.type==="reject-comments")m.innerHTML=rejectModal();if(state.modal.type==="rewrite-ai")m.innerHTML=rewriteModal();if(state.modal.type==="brand-projects")m.innerHTML=brandProjectModal();if(state.modal.type==="brand-manager")m.innerHTML=brandManagerModal();if(state.modal.type==="brand-edit")m.innerHTML=brandEditModal();if(state.modal.type==="brand-delete")m.innerHTML=brandDeleteModal();if(state.modal.type==="column-settings")m.innerHTML=columnSettingsModal();if(state.modal.type==="batch-reject")m.innerHTML=batchRejectModal();if(state.modal.type==="vendor-reject")m.innerHTML=vendorRejectModal();if(state.modal.type==="report-range")m.innerHTML=reportRangeModal()}
  function manualPostModal(){var single=state.manualPostMode==="single",brandOptions=tailBrands.map(function(brand){return'<option value="'+brand.id+'" '+(brand.id===state.manualPostBrand?'selected':'')+'>'+esc(brand.name)+'</option>'}).join("");return modalHead("添加主贴","补充未通过监测项目进入的公开 Web 新闻链接")+'<div class="tail-modal-body"><div class="tail-manual-post-top"><label class="tail-field"><span>归属品牌</span><select id="tailManualPostBrand">'+brandOptions+'</select></label><div class="tail-manual-post-destination"><strong>入库位置</strong><span>解析发布时间后自动进入对应时间段，默认保持未分派。</span></div></div><div class="tail-mode-switch tail-manual-mode"><button class="'+(single?'is-active':'')+'" data-tail-action="switch-manual-post-mode" data-mode="single">逐条添加</button><button class="'+(!single?'is-active':'')+'" data-tail-action="switch-manual-post-mode" data-mode="batch">Excel批量导入</button></div>'+(single?manualLinkRows():manualBatchPanel())+'</div><footer class="tail-modal-foot"><button class="tail-button" data-tail-action="close-modal">取消</button><button class="tail-button is-primary" data-tail-action="confirm-add-posts">'+(single?'添加并解析':'导入并解析')+'</button></footer>'}
  function manualLinkRows(){return'<section class="tail-manual-links"><div class="tail-manual-section-head"><div><strong>新闻链接</strong><span>仅支持 http:// 或 https:// 开头的 Web 端公开链接</span></div><b>'+state.manualUrls.length+' 条</b></div><div class="tail-manual-link-list">'+state.manualUrls.map(function(url,index){return'<div class="tail-manual-link-row"><b>'+(index+1)+'</b><label class="tail-field"><span>主贴链接</span><input type="url" data-manual-url-index="'+index+'" value="'+esc(url)+'" placeholder="https://www.example.com/news/..."></label><button class="tail-icon-button" title="删除该链接" aria-label="删除该链接" data-tail-action="remove-manual-link-row" data-url-index="'+index+'" '+(state.manualUrls.length===1?'disabled':'')+'>×</button></div>'}).join("")+'</div><button class="tail-button tail-add-link-row" data-tail-action="add-manual-link-row">＋ 继续添加链接</button></section>'}
  function manualBatchPanel(){var ready=!!state.manualFileName;return'<section class="tail-manual-batch"><div class="tail-template-row"><div><strong>1. 下载Excel模板</strong><span>模板中每行填写一条 Web 新闻链接，不要修改“主贴链接”列名。</span></div><button class="tail-button" data-tail-action="download-post-template">下载Excel模板</button></div><div class="tail-template-row is-upload"><div><strong>2. 上传已填写模板</strong><span>支持 .xlsx、.xls、.csv，系统会自动校验链接格式并去除重复项。</span></div><label class="tail-upload tail-post-file">选择本地文件<input id="tailPostFile" type="file" accept=".xlsx,.xls,.csv"></label></div>'+(ready?'<div class="tail-manual-file-ready"><div><strong>'+esc(state.manualFileName)+'</strong><span>已识别 '+state.manualBatchUrls.length+' 条有效链接 · 0 条重复 · 0 条格式异常</span></div><b>校验通过</b></div>':'<div class="tail-manual-file-empty">尚未选择批量导入文件</div>')+'</section>'}
  function brandProjectModal(){return modalHead("为“"+activeBrand().name+"”添加监测项目","搜索项目并点击添加，结果只会进入当前品牌的数据源")+'<div class="tail-modal-body"><div class="tail-project-toolbar"><label class="tail-field tail-project-search"><span>搜索监测项目</span><input id="tailProjectSearch" type="search" value="'+esc(state.projectKeyword)+'" placeholder="输入项目名称、品牌或关键词"></label>'+selectFieldHtml("tailProjectBrandScope","项目范围",[["current","当前品牌项目"],["all","全部项目"]],state.projectBrandScope).replace('id="tailProjectBrandScope"','id="tailProjectBrandScope" data-tail-project-filter="projectBrandScope"')+selectFieldHtml("tailProjectScene","业务场景",[["all","全部场景"],["event","专项事件"],["daily","日常声誉"],["campaign","传播活动"]],state.projectScene).replace('id="tailProjectScene"','id="tailProjectScene" data-tail-project-filter="projectScene"')+selectFieldHtml("tailProjectStatus","项目状态",[["running","运行中"],["all","全部状态"],["archived","已归档"]],state.projectStatus).replace('id="tailProjectStatus"','id="tailProjectStatus" data-tail-project-filter="projectStatus"')+'<button class="tail-button" data-tail-action="reset-project-filter">重置</button></div><div class="tail-project-table-wrap"><table class="tail-project-table"><thead><tr><th>监测项目</th><th>品牌</th><th>业务场景</th><th>平台</th><th>数据规模</th><th>最近更新</th><th>操作</th></tr></thead><tbody id="tailProjectTableBody">'+projectRowsHtml()+'</tbody></table></div><footer class="tail-project-footer"><span id="tailProjectCount">'+projectCountText()+'</span><div><button class="tail-button" data-tail-action="project-prev" '+(state.projectPage===1?'disabled':'')+'>上一页</button><span id="tailProjectPage">'+projectPageText()+'</span><button class="tail-button" data-tail-action="project-next" '+(state.projectPage>=projectMaxPage()?'disabled':'')+'>下一页</button></div></footer></div><footer class="tail-modal-foot"><button class="tail-button is-primary" data-tail-action="close-modal">完成</button></footer>'}
  function brandManagerModal(){return modalHead("品牌管理","统一维护尾翼数据设置、数据中心和任务页面使用的品牌范围")+'<div class="tail-modal-body"><div class="tail-brand-manager-head"><div><strong>当前 '+tailBrands.length+' 个品牌</strong><span>新增品牌会自动创建一套独立的空配置；品牌名称修改后同步现有内容。</span></div><button class="tail-button is-primary" data-tail-action="open-brand-edit">新增品牌</button></div><div class="tail-brand-manager-list">'+tailBrands.map(function(brand){var postCount=posts.filter(function(p){return p.brandId===brand.id}).length,taskCount=tasks.filter(function(t){var p=findPost(t.postId);return p&&p.brandId===brand.id}).length,sourceCount=activeConfigFor(brand.id).projectIds.length;return'<article class="tail-brand-manager-row"><div class="tail-brand-manager-name"><strong>'+esc(brand.name)+'</strong><span>'+esc(brand.desc)+'</span></div><div class="tail-brand-manager-stats"><span><b>'+sourceCount+'</b> 数据源</span><span><b>'+postCount+'</b> 条内容</span><span><b>'+taskCount+'</b> 个任务</span></div><div class="tail-row-actions"><button class="tail-button" data-tail-action="open-brand-edit" data-brand-id="'+brand.id+'">编辑</button><button class="tail-button is-danger" data-tail-action="request-delete-brand" data-brand-id="'+brand.id+'" '+(tailBrands.length===1?'disabled':'')+'>删除</button></div></article>'}).join("")+'</div><div class="tail-brand-manager-note">删除品牌只移除后续配置与品牌入口，不会删除已经生成的历史主贴、任务及佐证。</div></div><footer class="tail-modal-foot"><button class="tail-button is-primary" data-tail-action="close-modal">完成</button></footer>'}
  function brandEditModal(){var brand=findBrand(state.modal.id),editing=!!brand;return modalHead(editing?"编辑品牌":"新增品牌",editing?"修改后，数据设置和数据中心会同步更新品牌名称":"创建后即可为新品牌选择监测项目并配置初筛规则")+'<div class="tail-modal-body"><div class="tail-brand-edit-form"><label class="tail-field"><span>品牌名称</span><input id="tailBrandName" maxlength="20" value="'+esc(editing?brand.name:"")+'" placeholder="例如：新品牌"></label><label class="tail-field"><span>品牌业务说明</span><textarea id="tailBrandDesc" rows="4" maxlength="120" placeholder="说明该品牌覆盖的业务、车型或传播对象">'+esc(editing?brand.desc:"")+'</textarea><small>用于帮助配置人员区分各品牌的数据范围。</small></label></div></div><footer class="tail-modal-foot"><button class="tail-button" data-tail-action="open-brand-manager">返回</button><button class="tail-button is-primary" data-tail-action="save-brand-definition">'+(editing?"保存修改":"创建品牌")+'</button></footer>'}
  function brandDeleteModal(){var brand=findBrand(state.modal.id),postCount=brand?posts.filter(function(p){return p.brandId===brand.id}).length:0,taskCount=brand?tasks.filter(function(t){var p=findPost(t.postId);return p&&p.brandId===brand.id}).length:0;return modalHead("删除品牌配置","删除后该品牌不再出现在数据设置和数据中心的品牌选择中")+'<div class="tail-modal-body"><section class="tail-brand-delete-warning"><strong>确认删除“'+esc(brand?brand.name:"")+'”吗？</strong><span>该品牌当前关联 '+postCount+' 条内容、'+taskCount+' 个任务。历史记录继续保留原品牌名称，但该品牌的数据源和初筛配置会被移除。</span></section></div><footer class="tail-modal-foot"><button class="tail-button" data-tail-action="open-brand-manager">取消</button><button class="tail-button is-danger" data-tail-action="confirm-delete-brand">确认删除</button></footer>'}
  function assignModal(){var selected=posts.filter(function(p){return state.selected.indexOf(p.id)>-1});return modalHead("分派供应商任务",selected.length+"条主贴 · 每条主贴生成一个独立任务")+'<div class="tail-modal-body"><div class="tail-form-grid tail-assign-base">'+selectFieldHtml("tailAssignVendor","供应商",suppliers.map(opt),suppliers[0])+selectFieldHtml("tailAssignMode","评论撰写方式",[["human","供应商人工撰写"],["ai","AI撰写评论"]],state.assignMode)+'<label class="tail-field"><span>每条主贴评论数量</span><input id="tailCommentCount" type="number" min="1" max="100" step="1" value="10"><small>手动输入，默认10条</small></label></div><section id="tailHumanFields" class="tail-assign-mode-panel" '+(state.assignMode==="human"?"":"hidden")+'><div class="tail-section-title"><h3>人工撰写统一要求</h3><p>该要求会随任务发送给供应商，由供应商人工完成评论。</p></div><label class="tail-field"><textarea id="tailHumanRequirement" rows="5" placeholder="填写观点方向、语气、禁用表达和交付要求"></textarea></label></section><section id="tailAiFields" class="tail-assign-mode-panel" '+(state.assignMode==="ai"?"":"hidden")+'><div class="tail-section-title"><h3>AI撰写逐条设置</h3><p>每条主贴分别配置任务类型、车型、话术类型、人群、场景、语气和互动规则，生成后进入人工审核。</p></div><div class="tail-ai-requirement-list">'+selected.map(function(p,i){return aiRequirementCard(p,i)}).join("")+'</div></section></div><footer class="tail-modal-foot"><button class="tail-button" data-tail-action="close-modal">取消</button><button class="tail-button is-primary" data-tail-action="confirm-assign">确认分派</button></footer>'}
  function aiRequirementCard(p,index){var defaultAudience=["汽车行业关注者","普通网友"];return'<details class="tail-ai-requirement" '+(index===0?'open':'')+'><summary><div><strong>'+esc(p.title)+'</strong><span>'+esc(p.brand)+' · '+esc(p.model)+' · '+esc(p.platform)+'</span></div><em>逐条设置</em></summary><div class="tail-ai-config-grid">'+selectFieldHtml("tailAiTaskType-"+p.id,"任务类型",aiTaskTypes.map(opt),aiTaskTypes[0]).replace('id="tailAiTaskType-'+p.id+'"','id="tailAiTaskType-'+p.id+'" data-ai-task-type="'+p.id+'"')+selectFieldHtml("tailAiMainType-"+p.id,"话术主类型",aiMainTypes.map(opt),aiMainTypes[0]).replace('id="tailAiMainType-'+p.id+'"','id="tailAiMainType-'+p.id+'" data-ai-main-type="'+p.id+'"')+selectFieldHtml("tailAiScene-"+p.id,"适配上评场景",aiScenes.map(opt),sceneForPost(p)).replace('id="tailAiScene-'+p.id+'"','id="tailAiScene-'+p.id+'" data-ai-scene="'+p.id+'"')+selectFieldHtml("tailAiTone-"+p.id,"语气倾向",aiTones.map(opt),p.tone==="正面"?"正向夸赞":"理性克制").replace('id="tailAiTone-'+p.id+'"','id="tailAiTone-'+p.id+'" data-ai-tone="'+p.id+'"')+'<div class="tail-ai-multi is-model"><span>车型（可多选、搜索）</span><input type="search" data-ai-model-search="'+p.id+'" placeholder="搜索车型"><div class="tail-ai-checks">'+aiModels.map(function(model){return'<label data-model-option="'+p.id+'"><input type="checkbox" data-ai-model="'+p.id+'" value="'+model+'" '+(model===p.model||model==="全品牌"&&p.model==="全品牌"?'checked':'')+'><span>'+model+'</span></label>'}).join("")+'</div></div><div class="tail-ai-multi"><span>适配人群（可多选）</span><div class="tail-ai-checks is-audience">'+aiAudiences.map(function(audience){return'<label><input type="checkbox" data-ai-audience="'+p.id+'" value="'+audience+'" '+(defaultAudience.indexOf(audience)>-1?'checked':'')+'><span>'+audience+'</span></label>'}).join("")+'</div></div><label class="tail-field is-wide"><span>互动引导规则</span><textarea rows="3" data-ai-interaction="'+p.id+'">能带动互动，有共鸣、有讨论点，句式不一，短平快易传播、易跟评，占领用户心智。</textarea></label></div></details>'}
  function sceneForPost(p){var map={"高管相关":"高管相关","品牌价值":"品牌文化","产品硬实力":"产品硬实力","产品技术解读":"产品技术解读 & 测试","购车决策意向":"购车决策意向","用户用车体验":"用户用车体验","用户生态运营":"用户生态运营","市场与竞争舆情":"市场与竞争舆情","营销传播活动":"营销传播活动"};return map[p.category]||"品牌文化"}
