  function customSelectValue(selector){var el=qs(selector);if(!el)return"";if(el.value!=="自定义")return el.value;var input=qs('[data-custom-for="'+el.id+'"]');return input&&input.value.trim()||"自定义"}
  function downloadRangeReport(){var start=qs("#tailReportStart").value,end=qs("#tailReportEnd").value,startMs=new Date(start).getTime(),endMs=new Date(end).getTime();if(!start||!end||startMs>=endMs){toast("请选择有效的开始和结束时间");return}var rows=brandFilteredTasks().filter(function(t){var stamp=taskTimestamp(t.created);return stamp>=startMs&&stamp<endMs}),completed=rows.filter(function(t){return t.status==="completed"}).length,canvas=document.createElement("canvas"),ctx=canvas.getContext("2d"),range=start.replace("T"," ")+" 至 "+end.replace("T"," ");canvas.width=1200;canvas.height=1580;ctx.fillStyle="#f3f6f9";ctx.fillRect(0,0,1200,1580);ctx.fillStyle="#fff";ctx.fillRect(70,60,1060,1460);ctx.fillStyle="#e88624";ctx.fillRect(70,60,12,180);ctx.fillStyle="#13263e";ctx.font="700 42px Microsoft YaHei";ctx.fillText("尾翼维护任务报告",120,130);ctx.fillStyle="#728197";ctx.font="22px Microsoft YaHei";ctx.fillText(range,120,180);ctx.fillStyle="#23394f";ctx.font="700 28px Microsoft YaHei";ctx.fillText("范围核心指标",120,300);[["下发任务",rows.length+" 条"],["完成任务",completed+" 条"],["完成率",percent(completed,rows.length)],["进行中",rows.length-completed+" 条"]].forEach(function(item,i){var x=120+(i%2)*480,y=350+Math.floor(i/2)*140;ctx.fillStyle=i===1?"#fff6e9":"#f5f8fb";ctx.fillRect(x,y,430,105);ctx.fillStyle="#748398";ctx.font="20px Microsoft YaHei";ctx.fillText(item[0],x+22,y+34);ctx.fillStyle="#14283f";ctx.font="700 34px Microsoft YaHei";ctx.fillText(item[1],x+22,y+78)});ctx.fillStyle="#23394f";ctx.font="700 28px Microsoft YaHei";ctx.fillText("供应商完成情况",120,700);suppliers.forEach(function(v,i){var y=750+i*100,all=rows.filter(function(t){return t.vendor===v}).length,done=rows.filter(function(t){return t.vendor===v&&t.status==="completed"}).length;ctx.fillStyle="#f7f9fc";ctx.fillRect(120,y,960,72);ctx.fillStyle="#32475f";ctx.font="700 21px Microsoft YaHei";ctx.fillText(v,145,y+30);ctx.font="19px Microsoft YaHei";ctx.fillText("下发 "+all+" 条",500,y+30);ctx.fillText("完成 "+done+" 条",700,y+30);ctx.fillText(percent(done,all),900,y+30)});ctx.fillStyle="#718197";ctx.font="18px Microsoft YaHei";ctx.fillText("统计范围：当前所选品牌 · "+range,120,1420);canvas.toBlob(function(blob){var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="尾翼任务报告_"+start.slice(0,10)+"_"+end.slice(0,10)+".png";a.click();URL.revokeObjectURL(a.href)},"image/png");closeModal();toast("时间范围报告已生成")}

  function handleManualPostFile(file){if(!file)return;var ext=(file.name.split(".").pop()||"").toLowerCase();if(["xlsx","xls","csv"].indexOf(ext)<0){toast("请选择 .xlsx、.xls 或 .csv 文件");return}state.manualFileName=file.name;if(ext!=="csv"){state.manualBatchUrls=sampleBatchUrls();renderModal();toast("文件已上传并完成链接校验");return}var reader=new FileReader();reader.onload=function(){var rows=String(reader.result||"").split(/\r?\n/),urls=[];rows.forEach(function(row){var match=row.match(/https?:\/\/[^,，\s\"']+/i);if(match&&validWebUrl(match[0]))urls.push(match[0])});state.manualBatchUrls=unique(urls);renderModal();toast(state.manualBatchUrls.length?"已识别 "+state.manualBatchUrls.length+" 条有效链接":"未识别到有效 Web 链接")};reader.onerror=function(){state.manualBatchUrls=[];renderModal();toast("文件读取失败，请重新选择")};reader.readAsText(file,"utf-8")}
  function downloadPostTemplate(){var csv="主贴链接,备注\nhttps://www.example.com/news/123,示例链接（请删除）\n,每行填写一条Web端新闻链接";downloadBlob("\ufeff"+csv,"尾翼主贴批量导入模板.csv","text/csv;charset=utf-8");toast("Excel模板已下载")}
  function confirmAddPosts(){var links=state.manualPostMode==="single"?state.manualUrls.map(function(url){return url.trim()}).filter(Boolean):state.manualBatchUrls.slice();if(state.manualPostMode==="single"&&!links.length){toast("请至少填写一条主贴链接");return}if(state.manualPostMode==="batch"&&!state.manualFileName){toast("请先上传填写完成的Excel文件");return}if(state.manualPostMode==="batch"&&!links.length){toast("文件中没有可导入的有效链接");return}var invalid=links.filter(function(url){return !validWebUrl(url)});if(invalid.length){toast("有 "+invalid.length+" 条链接格式不正确，请检查后再添加");return}links=unique(links.map(normalizeWebUrl));var existing=posts.map(function(p){return normalizeWebUrl(p.url||"")}),fresh=links.filter(function(url){return existing.indexOf(url)<0});if(!fresh.length){toast("这些链接已经在尾翼数据中心中");return}var brand=findBrand(state.manualPostBrand)||tailBrands[0],slot=currentTimeSlot();fresh.forEach(function(url,index){posts.unshift(createManualPost(url,brand,slot,index))});if(state.selectedBrands.indexOf(brand.id)<0)state.selectedBrands.push(brand.id);state.tab="history";state.keyword="";persist();closeModal();render();toast("已添加 "+fresh.length+" 条主贴，已切换到全部数据"+(fresh.length<links.length?"，重复链接已跳过":""))}
  function createManualPost(url,brand,slot,index){var host=webHost(url),platform=manualPlatform(host),stamp=manualTimestamp();return post({id:"post-manual-"+Date.now().toString(36)+"-"+index,slot:slot,title:"手动添加主贴 · "+host,excerpt:"已通过Web链接补充进入尾翼数据中心，标题、作者与传播数据将在解析完成后自动回填。",url:url,brand:brand.name,brandId:brand.id,model:"待识别",tone:"待识别",category:"手动补充",platform:platform,media:host,mediaLevel:"待识别",accountType:"待识别",author:host,followers:0,engagement:0,reposts:0,comments:0,growth:0,potential:0,sentiment:"待识别",contentType:"网页新闻",publish:stamp,tags:["手动添加","Web链接"]})}
  function validWebUrl(value){try{var parsed=new URL(value);return parsed.protocol==="http:"||parsed.protocol==="https:"}catch(e){return false}}
  function normalizeWebUrl(value){try{var parsed=new URL(value);parsed.hash="";return parsed.href.replace(/\/$/,"")}catch(e){return String(value||"").trim()}}
  function webHost(value){try{return new URL(value).hostname.replace(/^www\./,"")}catch(e){return"待识别来源"}}
  function manualPlatform(host){if(host.indexOf("weibo")>-1)return"微博";if(host.indexOf("weixin")>-1||host.indexOf("qq.com")>-1)return"微信";if(host.indexOf("xiaohongshu")>-1)return"小红书";if(host.indexOf("douyin")>-1)return"抖音";if(host.indexOf("autohome")>-1)return"汽车之家";if(host.indexOf("zhihu")>-1)return"知乎";return"网站"}
  function currentTimeSlot(){var hour=new Date().getHours(),found=timeTabs.filter(function(tab){return hour>=tab.start&&hour<tab.end})[0];return found?found.id:"slot-1"}
  function manualTimestamp(){var now=new Date(),pad=function(n){return String(n).padStart(2,"0")};return now.getFullYear()+"-"+pad(now.getMonth()+1)+"-"+pad(now.getDate())+" "+pad(now.getHours())+":"+pad(now.getMinutes())}
  function sampleBatchUrls(){var token=Date.now().toString(36);return["https://news.example.com/article/"+token+"-01","https://www.autohome.com.cn/news/"+token+"-02","https://media.example.com/story/"+token+"-03"]}

  function findBrand(id){return tailBrands.filter(function(brand){return brand.id===id})[0]||null}
  function saveBrandDefinition(){var editing=findBrand(state.modal.id),name=(qs("#tailBrandName").value||"").trim(),desc=(qs("#tailBrandDesc").value||"").trim();if(!name){toast("请填写品牌名称");return}if(tailBrands.some(function(brand){return brand.name===name&&(!editing||brand.id!==editing.id)})){toast("品牌名称已存在");return}if(editing){var oldName=editing.name;editing.name=name;editing.desc=desc||name+"相关传播数据";posts.forEach(function(p){if(p.brandId===editing.id)p.brand=name});persist();render();openModal("brand-manager");toast(oldName===name?"品牌说明已更新":"品牌名称已同步更新");return}var id="brand-"+Date.now().toString(36);tailBrands.push({id:id,name:name,desc:desc||name+"相关传播数据"});state.brandConfigs[id]=createBrandConfigs()[id];state.selectedBrands.push(id);state.activeBrand=id;persist();render();openModal("brand-manager");toast("品牌已创建，请继续配置数据源和初筛规则")}
  function deleteBrandDefinition(id){if(tailBrands.length<=1){toast("至少保留一个品牌");return}var brand=findBrand(id);if(!brand){toast("未找到品牌");return}tailBrands=tailBrands.filter(function(item){return item.id!==id});delete state.brandConfigs[id];state.selectedBrands=state.selectedBrands.filter(function(item){return item!==id});if(state.activeBrand===id)state.activeBrand=tailBrands[0].id;persist();render();openModal("brand-manager");toast(brand.name+"已从品牌配置中删除")}
  function confirmAssign(){var vendor=qs("#tailAssignVendor").value,mode=qs("#tailAssignMode").value,count=Number(qs("#tailCommentCount").value),humanReq=qs("#tailHumanRequirement")?qs("#tailHumanRequirement").value.trim():"",autoApprove=!!(qs("#tailHumanAutoApprove")&&qs("#tailHumanAutoApprove").checked);if(!count||count<1||count>100){toast("评论数量请输入1至100之间的整数");return}if(mode==="human"&&!humanReq){toast("请填写人工撰写统一要求");return}state.selected.forEach(function(id){var p=findPost(id),settings=mode==="ai"?collectAiSettings(id,p):null,req=mode==="ai"?(settings.prompt||aiSettingsSummary(settings)):humanReq;p.assign=vendor;var cs=[];if(mode==="ai")for(var i=0;i<count;i++)cs.push(comment(generateAiComment(p,i,settings),"pending"));tasks.unshift(task({id:"task-"+Date.now()+"-"+id.slice(-3),postId:id,vendor:vendor,mode:mode,status:mode==="ai"?"internal_review":"vendor_pending",requirement:req,commentCount:count,aiSettings:settings,autoApprove:autoApprove,comments:cs}))});state.selected=[];persist();closeModal();render();toast(mode==="ai"?"AI已生成"+count+"条评论并进入内部审核":"任务已发送供应商，等待接收")}
  function saveTabFilter(){var id=state.modal.id;tabFilters[id]={platform:qs("#tailPlatform").value,mediaLevel:qs("#tailMediaLevel").value,fans:qs("#tailFans").value,engagement:qs("#tailEngagement").value,growth:qs("#tailGrowth").value,original:qs("#tailOriginal").value,account:qs("#tailAccount").value,sentiment:qs("#tailSentiment").value,contentType:qs("#tailContentType").value,includeKeyword:qs("#tailIncludeKeyword").value.trim(),excludeKeyword:qs("#tailExcludeKeyword").value.trim(),region:qs("#tailRegion").value};persist();closeModal();render();toast("当前时间段全部筛选条件已保存并生效")}
  function createTimeTab(){toast("14:00-15:00与“午间窗口”重叠，请先调整原时间段边界")}
  function deletePosts(ids){ids.forEach(function(id){var p=findPost(id);p.deleted=true;p.deletedAt="2026-08-14 10:00"});state.selected=[];persist();render();toast("信息已移入今日垃圾筐")}
  function submitVendorComments(t){var editors=qsa("[data-vendor-comment]"),missing=false;editors.forEach(function(editor){var index=Number(editor.getAttribute("data-vendor-comment")),existing=t.comments[index];if(existing&&existing.status==="approved")return;var value=editor.value.trim();if(!value){missing=true;return}if(existing){existing.text=value;existing.status=t.autoApprove?"approved":"pending";existing.rewriteRequirement=""}else t.comments[index]=comment(value,t.autoApprove?"approved":"pending")});if(missing||t.comments.length<t.commentCount){toast("请完整填写需要撰写或重写的评论内容");return}t.status=t.autoApprove?"export_ready":"vendor_submitted";t.feedback="";var round=currentRound(t);if(round)round.status=t.autoApprove?"待执行":"待审核";persist();render();toast(t.autoApprove?"评论已自动通过，可直接执行":"需重写的评论已提交，已通过评论保持不变")}
  function rewriteAiComment(){var t=findTask(state.modal.id),c=findComment(t,state.modal.extra),req=qs("#tailRewriteRequirement").value.trim();if(!req){toast("请填写本次重写要求");return}c.rewriteRequirement=req;c.text="结合主贴讨论来看，真正值得关注的是实际场景中的体验变化。"+req.replace(/[。！!]+$/,'')+"，这样的观点会更有参考价值。";c.status="pending";persist();closeModal();render();toast("AI已按新要求重新生成")}

  function visiblePosts(){return posts.filter(function(p){if(p.deleted||p.assign||!brandSelected(p))return false;if(!matchesTab(p)||!matchesSavedFilter(p))return false;if(state.keyword&&[p.title,p.media].concat(p.tags).join(" ").toLowerCase().indexOf(state.keyword.toLowerCase())<0)return false;return true}).sort(function(a,b){return b.publish.localeCompare(a.publish)})}
  function matchesTab(p){return state.tab==="history"||p.slot===state.tab}
  function matchesSavedFilter(p){if(state.tab==="history"||!tabFilters[state.tab])return true;var f=tabFilters[state.tab],text=[p.title,p.excerpt,p.media].concat(p.tags).join(" ");if(f.platform!=="全部平台"&&p.platform!==f.platform)return false;if(p.followers<filterNumber(f.fans))return false;if(p.engagement<filterNumber(f.engagement))return false;if(p.growth<filterNumber(f.growth))return false;if(f.mediaLevel!=="全部媒体"&&p.mediaLevel.indexOf("普通")>-1)return false;if(f.original==="仅原创"&&p.contentType.indexOf("原创")<0)return false;if(f.original==="原创及高影响转载"&&p.contentType.indexOf("原创")<0&&p.engagement<1000)return false;if(f.account==="媒体+KOL"&&p.accountType.indexOf("媒体")<0&&p.accountType.indexOf("KOL")<0)return false;if(f.account==="自然用户"&&p.accountType!=="自然用户")return false;if(f.account==="高活跃社区"&&p.mediaLevel.indexOf("社区")<0)return false;if(f.sentiment==="仅正面"&&p.sentiment!=="正面")return false;if(f.sentiment==="正面+中性"&&p.sentiment==="负面")return false;if(f.contentType==="图文"&&p.contentType.indexOf("图文")<0&&p.contentType.indexOf("文章")<0&&p.contentType.indexOf("笔记")<0)return false;if(f.contentType==="视频/直播"&&p.contentType.indexOf("视频")<0&&p.contentType.indexOf("直播")<0)return false;if(f.contentType==="论坛主贴"&&p.contentType.indexOf("论坛")<0)return false;if(f.includeKeyword&&!keywordMatch(text,f.includeKeyword,true))return false;if(f.excludeKeyword&&keywordMatch(text,f.excludeKeyword,false))return false;return true}
  function filterNumber(v){if(!v||v==="不限")return 0;var n=parseFloat(String(v).replace(/[^\d.]/g,""))||0;return String(v).indexOf("万")>-1?n*10000:n}
  function keywordMatch(text,value,all){var words=String(value).split(/[，,、\s]+/).filter(Boolean);if(!words.length)return false;return all?words.every(function(w){return text.indexOf(w)>-1}):words.some(function(w){return text.indexOf(w)>-1})}
  function matchMedia(p,v){if(v==="central")return p.mediaLevel.indexOf("中央")>-1;if(v==="industry")return p.mediaLevel.indexOf("行业")>-1||p.mediaLevel.indexOf("KOL")>-1;if(v==="community")return p.accountType==="自然用户"||p.mediaLevel.indexOf("社区")>-1;return true}
  function visibleTasks(){return brandFilteredTasks().filter(function(t){var created=taskTimestamp(t.created),start=state.taskStart?new Date(state.taskStart).getTime():null,end=state.taskEnd?new Date(state.taskEnd).getTime():null;if(start!==null&&created<start)return false;if(end!==null&&created>=end)return false;if(state.vendor!=="all"&&t.vendor!==state.vendor)return false;if(state.taskStatus!=="all"&&!taskGroupMatch(t,state.taskStatus))return false;return true})}
  function taskTimestamp(value){return new Date(String(value||"").replace(" ","T")).getTime()}
  function visibleVendorTasks(){return tasks.filter(function(t){if(t.vendor!=="星河传播")return false;if(state.taskScope==="today"&&!todayTask(t))return false;if(state.vendorStatus!=="all"&&!vendorGroupMatch(t,state.vendorStatus))return false;var p=findPost(t.postId);if(!p||!brandSelected(p))return false;return!state.keyword||[t.id,p.title,p.brand,p.model,p.platform,p.author].join(" ").toLowerCase().indexOf(state.keyword.toLowerCase())>-1})}
  function taskGroupMatch(t,g){var m={writing:["vendor_pending","vendor_writing","returned"],review:["vendor_submitted","internal_review"],executing:["export_ready","vendor_executing"],validation:["evidence_review"],rejected:["vendor_rejected"],completed:["completed"]};return(m[g]||[]).indexOf(t.status)>-1}
  function vendorGroupMatch(t,g){var m={receiving:["vendor_pending"],writing:["vendor_writing","returned"],waiting:["vendor_submitted","internal_review"],executable:["export_ready"],executing:["vendor_executing","evidence_review"],rejected:["vendor_rejected"],completed:["completed"]};return(m[g]||[]).indexOf(t.status)>-1}

  function stepper(t){var order=page==="vendor-detail"?["接收任务","评论撰写","等待审核","执行维护","验收完成"]:["分派任务","评论撰写","内部审核","供应商执行","验收完成"],idx=stageIndex(t.status);return'<section class="tail-stepper">'+order.map(function(s,i){return'<div class="tail-step '+(i<idx?'is-done':i===idx?'is-active':'')+'"><b>'+(i<idx?'✓':i+1)+'</b><span>'+s+'</span></div>'}).join("")+'</section>'}
