  function sourceBlock(p){return'<div class="tail-block-head"><h2>主贴原文</h2><button class="tail-button" data-tail-action="open-original" data-post-id="'+p.id+'">打开原文</button></div><h2 class="tail-source-title">'+esc(p.title)+'</h2><div class="tail-source-meta"><span>'+esc(p.platform)+' · '+esc(p.media)+'</span><span>'+esc(p.publish)+'</span><span>粉丝 '+format(p.followers)+'</span><span>互动 '+format(p.engagement)+'</span></div><div class="tail-source-content">'+esc(p.excerpt)+'</div>'}
  function taskSummary(t,p){var settings=t.aiSettings||null,ai=settings?'<div class="tail-ai-settings-summary"><strong>AI生成设置</strong><span>任务类型：'+esc(settings.taskType||"-")+'</span><span>车型：'+esc((settings.models||[]).join("、")||p.model)+'</span><span>话术类型：'+esc(settings.mainType||"-")+'</span><span>适配人群：'+esc((settings.audiences||[]).join("、")||"-")+'</span><span>上评场景：'+esc(settings.scene||"-")+'</span><span>语气倾向：'+esc(settings.tone||"-")+'</span><span class="is-wide">互动规则：'+esc(settings.interaction||"-")+'</span></div>':"";return'<div class="tail-block-head"><h2>任务信息</h2>'+taskStatus(t.status)+'</div><div class="tail-task-meta-grid"><span><b>任务编号</b>'+esc(t.id.toUpperCase())+'</span><span><b>评论方式</b>'+(t.mode==="ai"?'AI撰写':'供应商人工撰写')+'</span><span><b>评论数量</b>'+t.commentCount+' 条</span><span><b>'+(page==="vendor-detail"?'接收时间':'下发时间')+'</b>'+t.created+'</span></div><div class="tail-task-requirement"><strong>'+(t.mode==="ai"?'评论生成要求':'人工撰写统一要求')+'</strong><p>'+esc(t.requirement)+'</p></div>'+ai}
  function evidenceBlock(t){return'<div class="tail-evidence-groups">'+evidenceGroups(t).map(function(group){return'<section class="tail-evidence-group"><div class="tail-evidence-group-head"><div><strong>'+group.title+'</strong><span>'+group.desc+'</span></div><b>'+group.files.length+' 张</b></div><div class="tail-evidence-grid">'+(group.files.length?group.files.map(function(f,i){return'<button class="tail-evidence-thumb" title="'+esc(f)+'"><span>截图 '+(i+1)+'</span><em>'+esc(f.split("｜").pop())+'</em></button>'}).join(""):'<div class="tail-evidence-empty">暂无该类材料</div>')+'</div></section>'}).join("")+'</div>'+(t.aiValidation?'<div class="tail-ai-result" style="margin-top:10px"><strong>智能校验 '+t.aiValidation.score+'分</strong>'+esc(t.aiValidation.summary)+'</div>':'')}
  function evidenceGroups(t){var defs=[{key:"before",title:"维护前原始截图",desc:"执行前原始状态，固定1张",terms:["维护前原始截图","处理前"]},{key:"after72",title:"72小时看管监控截图",desc:"维护后72小时看管结果，固定1张",terms:["72小时看管监控截图","72小时后"]},{key:"comments",title:"单评 / 多评维护处置截图",desc:"每条评论对应处置结果，可达几十张",terms:["单评 / 多评维护处置截图","评论发布"]},{key:"reports",title:"举报操作截图",desc:"举报提交、受理和反馈，多张",terms:["举报操作截图","举报"]}];var used={};return defs.map(function(def){var files=t.evidence.filter(function(file){var match=def.terms.some(function(term){return file.indexOf(term)>-1});if(match)used[file]=true;return match});return{title:def.title,desc:def.desc,files:files}}).concat(t.evidence.some(function(f){return !used[f]})?[{title:"其他历史材料",desc:"旧任务归档材料",files:t.evidence.filter(function(f){return !used[f]})}]:[])}
  function roundStatusFromTask(status){if(status==="vendor_pending"||status==="vendor_writing"||status==="returned")return"评论撰写";if(status==="vendor_submitted"||status==="internal_review")return"内容审核";if(status==="export_ready"||status==="vendor_executing")return"供应商执行";if(status==="evidence_review")return"等待验收";if(status==="completed")return"已完成";return"进行中"}
