  function normalizeBrandPlatforms(){tailBrands.forEach(function(brand){var config=state.brandConfigs[brand.id],legacy=config&&config.platforms;if(!config||!Array.isArray(legacy)||!legacy.length)return;if(legacy.every(function(item){return item.indexOf("|")>-1}))return;var next=[];function addGroup(id,limit){var group=platformGroups.filter(function(item){return item.id===id})[0];if(group)next=next.concat((limit||group.items).map(function(item){return platformKey(id,item)}))}legacy.forEach(function(item){if(item.indexOf("|")>-1){next.push(item);return}if(item==="微博")addGroup("weibo");else if(item==="微信")addGroup("wechat");else if(item==="抖音"||item==="快手")next.push(platformKey("video",item));else if(item==="小红书")next.push(platformKey("app",item));else if(item==="新闻网站"||item==="新闻客户端")addGroup("website");else if(item==="汽车垂直")addGroup("website",["汽车之家","易车网","懂车帝","太平洋汽车","爱卡汽车","网上车市","汽车头条"]);else if(item==="论坛/贴吧")addGroup("forum");else if(item==="其他")platformGroups.forEach(function(group){group.items.filter(function(media){return media.indexOf("其他")===0}).forEach(function(media){next.push(platformKey(group.id,media))})})});config.platforms=unique(next)})}
